insert into dd_owner_attention_queue(domain,source_table,source_record_id,reason,priority,recommended_action,metadata) select 'SALES','dd_sales_queue',s.id::text,'Speed-to-lead SLA exceeded','P1','Review and respond through Sales.',jsonb_build_object('source',s.source,'age_minutes',round(extract(epoch from(now()-coalesce(s.source_occurred_at,s.created_at)))/60)) from dd_sales_queue s where coalesce(s.do_not_contact,false)=false and s.disposition='NOT_CONTACTED' and(s.phone is not null or s.email is not null) and coalesce(s.source_occurred_at,s.created_at)<now()-interval '30 minutes' on conflict do nothing;get diagnostics n=row_count;t:=t+n;
insert into dd_owner_attention_queue(domain,source_table,source_record_id,reason,priority,recommended_action,metadata) select 'OPERATIONS','dd_jobs',j.id::text,'Job SLA deadline exceeded','P0','Review assignment/status and recover the job.',jsonb_build_object('job_status',j.job_status,'sla_due_at',j.sla_due_at) from dd_jobs j where j.sla_due_at is not null and j.sla_due_at<now() and coalesce(j.job_status,'') not in('COMPLETED','CANCELLED','CLOSED') on conflict do nothing;get diagnostics n=row_count;t:=t+n;
insert into dd_owner_attention_queue(domain,source_table,source_record_id,reason,priority,recommended_action,metadata) select 'QA','dd_jobs',j.id::text,'Completed job has no job evidence','P0','Collect/verify required evidence before closeout.',jsonb_build_object('job_status',j.job_status) from dd_jobs j where j.job_status in('COMPLETED','CLOSED') and not exists(select 1 from dd_job_evidence e where e.job_id=j.id) on conflict do nothing;get diagnostics n=row_count;t:=t+n;
insert into dd_automation_recipe_runs(id,recipe_key,status,matched_count,actioned_count,evidence,completed_at) values(r,'safe_automation_sweep','COMPLETED',t,t,jsonb_build_object('mode','detect_and_queue','external_side_effects',false),now());update dd_automation_recipes set last_run_at=now() where is_active;return r;end$$;
