
create or replace function public.dd_run_service_discovery_controller() returns uuid language plpgsql security definer set search_path='public' as $$declare r uuid:=gen_random_uuid(); n int:=0;s int:=0;begin select count(*) into s from dd_service_discovery_candidates where underwriting_status='RESEARCH_ONLY';insert into dd_research_work_queue(program_key,work_key,question,required_evidence,priority,status,blocker,next_action,owner_decision_required,metadata) select 'SERVICE_DISCOVERY','candidate:'||c.candidate_key,'Determine whether "'||c.service_name||'" is beneficial and safe for DANI DECLARES to add. Validate demand, duplication, licensing/regulatory boundaries, insurance, safety, provider capability, equipment, workflow, channel fit, economics and fulfillment.','Current market evidence; authoritative regulatory evidence where applicable; insurance/safety; provider capability; economics; scope/exclusions; channel fit.',case c.research_priority when 'HIGH' then 'P1' else 'P2' end,'QUEUED','ACTIVATION_PROHIBITED_UNTIL_ALL_GATES_PASS','Research candidate gates. Keep RESEARCH_ONLY while any gate is unresolved.',false,jsonb_build_object('candidate_id',c.id,'activation_prohibited',true) from dd_service_discovery_candidates c where c.underwriting_status='RESEARCH_ONLY' on conflict(program_key,work_key) do update set question=excluded.question,required_evidence=excluded.required_evidence,priority=excluded.priority,blocker=excluded.blocker,next_action=excluded.next_action,metadata=excluded.metadata,updated_at=now();get diagnostics n=row_count;update dd_service_discovery_candidates set release_eligible=false,activation_prohibited=true,updated_at=now() where underwriting_status<>'RELEASED';insert into dd_service_discovery_runs(id,status,candidates_scanned,research_items_created,blocked_from_activation,evidence,completed_at) values(r,'COMPLETED',s,n,(select count(*) from dd_service_discovery_candidates where activation_prohibited),jsonb_build_object('auto_activation',false,'owner_review_before_release',true),now());return r;end$$;
create or replace function public.dd_run_safe_automation_recipes() returns uuid language plpgsql security definer set search_path='public' as $$declare r uuid:=gen_random_uuid();n int:=0;t int:=0;begin
on conflict(recipe_key) do update set recipe_name=excluded.recipe_name,domain=excluded.domain,trigger_type=excluded.trigger_type,execution_mode=excluded.execution_mode,risk_tier=excluded.risk_tier,is_active=true,owner_attention_on_match=excluded.owner_attention_on_match,cooldown_minutes=excluded.cooldown_minutes,condition_spec=excluded.condition_spec,action_spec=excluded.action_spec,updated_at=now();
on conflict(domain) do update set auto_research=excluded.auto_research,auto_reconcile_low_risk=excluded.auto_reconcile_low_risk,owner_required_actions=excluded.owner_required_actions,notes=excluded.notes,updated_at=now();
